"""Tests for the exact Tupper formula core (no Qt import here)."""

from __future__ import annotations

import random
from fractions import Fraction

import pytest

from app.core.tupper import (
    HEIGHT,
    ORIGINAL_K,
    WIDTH,
    cell_is_black,
    decode,
    decode_n,
    encode,
    formula_holds,
    parse_k,
    plot_tile,
    rows_from_bitmap,
)

