    ".#......#..................#..#..#.#.#.......#.#..#..#..#....#.#.#.#.#.#.#.#..#.#.#.#....#.#...#......#..#",
    ".#......#..................#..#..#.#.#.......#.#..#.#.#.#....#.#.#.###.###.#..#..#..#....#.#...#......#..#",
    ".#......#...............#.#...#...#..#..##........#.....#..................#..#.#...#..#.......#...##..#.#",
    "###...#.#...............#.#...#..#...#.#..#.......#.....#...................#.#.....#..#......#...#..#.#.#",
    ".....#..#.##.#...##...###.#...#......#...#........###.###...................#.###.###.#.......#.....#..#.#",
    "###.#...#.#.#.#.#..#.#..#.#...#.####.#..#..........................................................#...#.#",
    ".....#..#.#.#.#.#..#.#..#.#...#......#.#..........................................................#....#.#",
