def test_original_k_is_543_digits():
    assert len(str(ORIGINAL_K)) == 543
    assert ORIGINAL_K % 17 == 0


def test_original_k_plots_the_formula():
    bitmap = decode(ORIGINAL_K)
    assert rows_from_bitmap(bitmap) == SELF_PORTRAIT


def test_original_k_roundtrip():
    assert encode(decode(ORIGINAL_K)) == ORIGINAL_K


def test_random_bitmaps_roundtrip():
    rng = random.Random(2001)
    for _ in range(24):
        bitmap = [[rng.randint(0, 1) for _ in range(WIDTH)] for _ in range(HEIGHT)]
        k = encode(bitmap)
        assert decode(k) == bitmap
        assert encode(decode(k)) == k
        assert k % 17 == 0


def test_empty_image():
    bitmap = [[0] * WIDTH for _ in range(HEIGHT)]
    k = encode(bitmap)
    assert k == 0
    assert decode(k) == bitmap
    assert rows_from_bitmap(decode(k)) == ["." * WIDTH] * HEIGHT


def test_full_image():
    bitmap = [[1] * WIDTH for _ in range(HEIGHT)]
    k = encode(bitmap)
    assert k == 17 * ((1 << (WIDTH * HEIGHT)) - 1)
    assert decode(k) == bitmap
    assert rows_from_bitmap(decode(k)) == ["#" * WIDTH] * HEIGHT


def test_decode_rejects_negative():
    with pytest.raises(ValueError):
        decode(-17)


def test_parse_k_ignores_layout():
    assert parse_k(" 960 939-379\n918 \t") == 960939379918
    with pytest.raises(ValueError):
        parse_k("k = ...")


def test_formula_matches_cell_bits():
    """The bit shortcut must equal the published inequality, literally."""
    rng = random.Random(7)
    for k in (ORIGINAL_K, 17 * 12345, 17 * ((1 << 1802) - 1)):
        n = k // 17
        for _ in range(60):
            col = rng.randrange(WIDTH)
            row = rng.randrange(HEIGHT)
            x = Fraction(WIDTH - 1 - col) + Fraction(1, 2)
            y = Fraction(17 * n + row) + Fraction(1, 2)
            expected = cell_is_black(n, col, row) == 1
            assert formula_holds(x, y, k) is expected

    # And a couple of points deliberately outside the portrait band.
    assert formula_holds(0.5, 0.5, ORIGINAL_K) is False


def test_plot_tile_band_matches_decode():
    k = ORIGINAL_K
    tile = plot_tile(k, 0.0, 0.0, 1.0, WIDTH, HEIGHT)
    bitmap = decode(k)
    for row in range(HEIGHT):
        for col in range(WIDTH):
            assert tile[row * WIDTH + col] == bitmap[row][col]

    big = plot_tile(k, 0.0, 0.0, 8.0, WIDTH * 8, HEIGHT * 8)
    for row in range(HEIGHT):
        for col in range(WIDTH):
            assert big[(row * 8 + 3) * WIDTH * 8 + col * 8 + 5] == bitmap[row][col]


def test_plot_tile_anisotropic_scale():
    """The strip graph uses independent x/y scales; cells must stay exact."""
    bitmap = decode(ORIGINAL_K)
    sx, sy = 6.0, 2.0
    tile = plot_tile(ORIGINAL_K, 0.0, 0.0, sx, WIDTH * 6, HEIGHT * 2, scale_y=sy)
    for row in range(HEIGHT):
        for col in range(WIDTH):
            assert tile[(row * 2 + 1) * WIDTH * 6 + col * 6 + 3] == bitmap[row][col]


def test_plot_tile_shows_neighbouring_bitmaps():
    """k +/- 17 is a different bitmap: the noise around the portrait."""
    n_ref = ORIGINAL_K // 17
    # Display v increases with y, so the band above y=k is n-1 and the one
    # below is n+1 (the plane is continuous, the frame is just a window).
    above = plot_tile(ORIGINAL_K, 0.0, -17.0, 1.0, WIDTH, HEIGHT)
    expected_above = decode_n(n_ref - 1)
    below = plot_tile(ORIGINAL_K, 0.0, 17.0, 1.0, WIDTH, HEIGHT)
    expected_below = decode_n(n_ref + 1)
    for row in range(HEIGHT):
        for col in range(WIDTH):
            assert above[row * WIDTH + col] == expected_above[row][col]
            assert below[row * WIDTH + col] == expected_below[row][col]
    assert above != expected_below


def test_plot_tile_subpixel_path():
    tile = plot_tile(ORIGINAL_K, 0.0, 0.0, 0.5, 106, 17, samples=1)
    assert len(tile) == 106 * 17
    assert any(tile)
    # Far from the portrait there are no black cells at all.
    empty = plot_tile(ORIGINAL_K, 0.0, 17.0 * 40, 4.0, 8, 8)
    assert not any(empty)


def test_plot_tile_outside_x_range_is_blank():
    tile = plot_tile(ORIGINAL_K, -20.0, 0.0, 1.0, 20, 17)
    assert not any(tile)


def test_plot_tile_invalid_scale():
    with pytest.raises(ValueError):
        plot_tile(ORIGINAL_K, 0.0, 0.0, 0.0, 10, 10)
